# Expected values generated by test/scipy/gen_linalg3.py (scipy 1.18.1).
# qr_update/qr_insert/qr_delete/qr_multiply, cdf2rdf, eigh_tridiagonal 'stemr',
# eig_banded with complex select.
import numpy as np
import scipy.linalg as sl
import linalg3_expected as X

def close(x, ref, rtol: float = 1e-9, atol: float = 1e-11) -> bool:
    a = np.asarray(x).ravel()
    if a.shape[0] != len(ref):
        print('size', a.shape[0], len(ref))
        return False
    ok = True
    for i in range(len(ref)):
        if abs(a[i] - ref[i]) > atol + rtol * abs(ref[i]):
            print('mismatch', i, a[i], ref[i])
            ok = False
    return ok

def closeabs(x, ref, rtol: float = 1e-8, atol: float = 1e-10) -> bool:
    a = np.asarray(x).ravel()
    ok = a.shape[0] == len(ref)
    for i in range(len(ref)):
        if abs(abs(a[i]) - abs(ref[i])) > atol + rtol * abs(ref[i]):
            print('mismatch', i, a[i], ref[i])
            ok = False
    return ok

def check(cond: bool, what: str):
    if not cond:
        print('TEST FAILED:', what)

def A6():
    return np.array(X.A).reshape((6, 4))

def test_update_delete():
    A = A6()
    Qf, Rf = sl.qr(A)
    Qe, Re = sl.qr(A, mode='economic')
    u = np.array(X.u6)
    v = np.array(X.v4)
    q, r = sl.qr_update(Qf, Rf, u, v)
    check(close(q, X.upd_full_q) and close(r, X.upd_full_r), 'qr_update full')
    q, r = sl.qr_update(Qe, Re, u, v)
    check(close(q, X.upd_eco_q) and close(r, X.upd_eco_r), 'qr_update economic')
    q, r = sl.qr_delete(Qf, Rf, 2, 1, 'row')
    check(close(q, X.delr_full_q) and close(r, X.delr_full_r), 'delete row full')
    q, r = sl.qr_delete(Qe, Re, 2, 1, 'row')
    check(close(q, X.delr_eco_q) and close(r, X.delr_eco_r), 'delete row economic')
    q, r = sl.qr_delete(Qf, Rf, 1, 1, 'col')
    check(close(q, X.delc_full_q) and close(r, X.delc_full_r), 'delete col full')
    q, r = sl.qr_delete(Qe, Re, 1, 1, 'col')
    check(close(q, X.delc_eco_q) and close(r, X.delc_eco_r), 'delete col economic')
    q, r = sl.qr_delete(Qf, Rf, 1, 2, 'row')
    check(close(q @ r, X.delrp_full_prod), 'delete rows p=2 product')
    q, r = sl.qr_delete(Qf, Rf, 0, 2, 'col')
    check(close(q @ r, X.delcp_full_prod), 'delete cols p=2 product')

def test_insert():
    A = A6()
    Qf, Rf = sl.qr(A)
    Qe, Re = sl.qr(A, mode='economic')
    ur = np.array(X.ur4)
    uc = np.array(X.uc6)
    q, r = sl.qr_insert(Qf, Rf, ur, 3, 'row')
    check(close(q, X.insr_full_q) and close(r, X.insr_full_r), 'insert row full')
    q, r = sl.qr_insert(Qe, Re, ur, 3, 'row')
    check(close(q, X.insr_eco_q) and close(r, X.insr_eco_r), 'insert row economic')
    q, r = sl.qr_insert(Qf, Rf, uc, 2, 'col')
    check(close(q, X.insc_full_q) and close(r, X.insc_full_r), 'insert col full')
    A2 = np.array(X.A2).reshape((6, 3))
    Q2, R2 = sl.qr(A2, mode='economic')
    q, r = sl.qr_insert(Q2, R2, uc, 1, 'col')
    check(close(q, X.insc_eco_q) and close(r, X.insc_eco_r), 'insert col economic')
    urp = np.array(X.urp).reshape((2, 4))
    q, r = sl.qr_insert(Qf, Rf, urp, 1, 'row')
    check(close(q @ r, X.insrp_full_prod), 'insert rows p=2 product')

def test_multiply_cdf():
    A = A6()
    c = np.array(X.c36).reshape((3, 6))
    cq, r = sl.qr_multiply(A, c)
    check(close(cq, X.qm_right) and close(r, X.qm_r), 'qr_multiply right')
    cl = np.array(X.c42).reshape((4, 2))
    cq, r = sl.qr_multiply(A, cl, mode='left')
    check(close(cq, X.qm_left), 'qr_multiply left')
    cq, r, p = sl.qr_multiply(A, c, pivoting=True)
    check(close(cq, X.qm_piv) and close(p, X.qm_piv_p), 'qr_multiply pivoting')
    w = np.array([complex(a, b) for a, b in zip(X.cdf_w_re, X.cdf_w_im)])
    vv = np.array([complex(a, b) for a, b in zip(X.cdf_v_re, X.cdf_v_im)]).reshape((3, 3))
    wr, vr = sl.cdf2rdf(w, vv)
    check(close(wr, X.cdf_wr) and close(vr, X.cdf_vr), 'cdf2rdf')

def test_eigen_variants():
    d = np.array([2.0, 3.0, 1.5, 4.0, 2.5])
    e = np.array([0.5, -0.3, 0.8, 0.2])
    w = sl.eigh_tridiagonal(d, e, eigvals_only=True, lapack_driver='stemr')
    check(close(w, X.stemr_w), 'stemr eigvals')
    w, v = sl.eigh_tridiagonal(d, e, lapack_driver='stemr')
    check(close(w, X.stemr_w2) and closeabs(v, X.stemr_v_abs), 'stemr eigh')
    w, v = sl.eigh_tridiagonal(d, e, select='i', select_range=(1, 3), lapack_driver='stemr')
    check(close(w, X.stemr_sel_w) and closeabs(v, X.stemr_sel_vabs), 'stemr select')
    ab = np.array([[0, 1 + 1j, 0.5j, 2.0, 1.0], [2.0, 3.0, 1.0, 4.0, 2.5]], dtype=complex)
    w = sl.eigvals_banded(ab, select='v', select_range=(1.0, 4.0))
    check(close(w, X.hb_w), 'eigvals_banded complex value select')
    w, v = sl.eig_banded(ab, select='i', select_range=(0, 2))
    check(close(w, X.hb_w2) and closeabs(v, X.hb_vabs), 'eig_banded complex index select')

test_update_delete()
test_insert()
test_multiply_cdf()
test_eigen_variants()
print('linalg3 OK')
